  --secondary: rgb(41, 48, 64);
  --secondary-foreground: rgb(228, 228, 228);
  --muted: rgb(41, 48, 64);
  --muted-foreground: rgb(164, 164, 164);
  --accent: rgb(42, 54, 87);
  --accent-foreground: rgb(189, 218, 255);
  --destructive: rgb(241, 68, 68);
  --destructive-foreground: rgb(255, 255, 255);
  --border: rgb(60, 66, 83);
  --input: rgb(60, 66, 83);
  --ring: rgb(223, 94, 58);
  --chart-1: rgb(136, 168, 201);
  --chart-2: rgb(231, 160, 142);
  --chart-3: rgb(89, 125, 169);
  --chart-4: rgb(71, 100, 145);
  --chart-5: rgb(48, 74, 131);
  --radius: 0.75rem;
  --sidebar: rgb(42, 48, 64);
  --sidebar-foreground: rgb(228, 228, 228);
  --sidebar-primary: rgb(223, 94, 58);
  --sidebar-primary-foreground: rgb(255, 255, 255);
